import {createClient} from "https://esm.sh/@supabase/supabase-js@2.75.1";
const cfg=window.YUANJIE_CONFIG,allowedEmail="lijie5868@gmail.com";
const basePath=location.pathname.replace(/admin\/?$/,''),supabase=createClient(cfg.supabaseUrl,cfg.publishableKey),$=id=>document.getElementById(id);
let pages=[],current=null;
function message(text,error=false){$('appMessage').textContent=text;$('appMessage').style.color=error?'#a02d22':'#37643c'}
function editorDocument(html){return `<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><link rel="stylesheet" href="${basePath}style.css"><style>body{margin:0;padding:18px;background:#fff}a{pointer-events:none}</style></head><body>${html}</body></html>`}
function loadEditor(page){current=page;$('title').value=page.title;$('description').value=page.meta_description;const frame=$('visualEditor');frame.srcdoc=editorDocument(page.main_html);frame.onload=()=>{frame.contentDocument.designMode='on'};document.querySelectorAll('#pageList button').forEach(b=>b.classList.toggle('active',b.dataset.slug===page.slug));$('savedAt').textContent=page.updated_at?`上次儲存：${new Date(page.updated_at).toLocaleString('zh-TW')}`:'';message('')}
function mainHtml(){const main=$('visualEditor').contentDocument.querySelector('main');if(!main)throw new Error('頁面內容缺少 main 區塊，請重新載入後再試。');return main.outerHTML}
async function fetchPages(){const{data,error}=await supabase.from('cms_pages').select('*').order('sort_order');if(error)throw error;pages=data;$('pageList').innerHTML='';for(const page of pages){const b=document.createElement('button');b.textContent=page.title;b.dataset.slug=page.slug;b.onclick=()=>loadEditor(page);$('pageList').append(b)}if(pages.length)loadEditor(pages[0])}
async function saveDraft(){const payload={title:$('title').value.trim(),meta_description:$('description').value.trim(),main_html:mainHtml(),updated_at:new Date().toISOString()};const{data,error}=await supabase.from('cms_pages').update(payload).eq('id',current.id).select().single();if(error)throw error;Object.assign(current,data);loadEditor(current);message('草稿已儲存，正式網站尚未變更。')}
async function publish(){await saveDraft();const payload={slug:current.slug,file_name:current.file_name,title:current.title,meta_description:current.meta_description,main_html:current.main_html,sort_order:current.sort_order,published_at:new Date().toISOString()};const{error}=await supabase.from('published_pages').upsert(payload,{onConflict:'slug'});if(error)throw error;message('發布完成。系統將在約 5 分鐘內更新正式網站。')}
$('loginForm').onsubmit=async event=>{event.preventDefault();const email=$('email').value.trim().toLowerCase();if(email!==allowedEmail){$('loginMessage').textContent='此信箱沒有後台權限。';return}const{error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:location.href,shouldCreateUser:true}});$('loginMessage').textContent=error?error.message:'登入連結已寄出，請到信箱收信。'};
$('save').onclick=()=>saveDraft().catch(e=>message(e.message,true));$('publish').onclick=()=>publish().catch(e=>message(e.message,true));$('signOut').onclick=()=>supabase.auth.signOut();
document.querySelectorAll('[data-command]').forEach(button=>button.onclick=()=>{const command=button.dataset.command,value=command==='createLink'?prompt('請輸入連結網址'):null;$('visualEditor').contentDocument.execCommand(command,false,value)});
$('imageUpload').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${Date.now()}-${safe}`;const{error}=await supabase.storage.from('site-media').upload(path,file,{upsert:false});if(error)throw error;const{data}=supabase.storage.from('site-media').getPublicUrl(path);$('visualEditor').contentDocument.execCommand('insertImage',false,data.publicUrl);message('圖片已上傳並插入草稿。記得儲存或發布。')}catch(e){message(e.message,true)}};
supabase.auth.onAuthStateChange(async(_event,session)=>{const valid=session?.user?.email?.toLowerCase()===allowedEmail;$('login').hidden=valid;$('app').hidden=!valid;$('signOut').hidden=!valid;if(valid&&!pages.length)fetchPages().catch(e=>message(e.message,true))});

